    public static function key(string $source):string{return 'tax_auto_draft_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array{$english=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$source=>$text)$out[self::key($source)]=$english?$text:$source;return$out;}
    public static function text(string $source,array $messages,array $values=[]):string
    {
        if(isset($messages[self::key($source)]))$text=$messages[self::key($source)];
        elseif(preg_match('/\A([0-9]{4}): (.+)\z/sD',$source,$m))$text=$m[1].': '.self::text($m[2],$messages);
        elseif(preg_match('/\AGesamteinnahmen ([0-9]{4}) aus dem abgestimmten Zahlungsjournal; volle Euro geprüft\z/D',$source,$m))return self::text('Gesamteinnahmen {year} aus dem abgestimmten Zahlungsjournal; volle Euro geprüft',$messages,['year'=>$m[1]]);
        elseif(preg_match('/\AFür ([0-9]{4}) bitte die Erklärung in Mein ELSTER vorbereiten\.\z/D',$source,$m))return self::text('Für {year} bitte die Erklärung in Mein ELSTER vorbereiten.',$messages,['year'=>$m[1]]);
        elseif(str_ends_with($source,' – diesen Sonderfall vor automatischer Übernahme klären.'))$text=self::text(substr($source,0,-strlen(' – diesen Sonderfall vor automatischer Übernahme klären.')),$messages).' '.self::text('– diesen Sonderfall vor automatischer Übernahme klären.',$messages);
        elseif(str_contains($source,': ')){[$label,$detail]=explode(': ',$source,2);$text=self::text($label,$messages).': '.self::text($detail,$messages);}
        else$text=TaxAutoPackageMessages::text($source,$messages,$values);
        foreach($values as$key=>$value)if(is_scalar($value))$text=str_replace('{'.$key.'}',(string)$value,$text);return$text;
    }
}
